resource Stash { s: Signer }

public fn steal(s: Signer) {
  move_to(addr_of(s), Stash { s: s })
}

public fn who(): address {
  let Stash { s } = move_from<Stash>(@coin);
  let a = addr_of(s);
  move_to(@coin, Stash { s: s });
  a
}

